

import React, { useState, useEffect } from "react";

import "./styles.css"
import {  SvgIcon_Cmpt } from "../../../components";
import {  useNavigate, useLocation } from "react-router-dom";
import {  getStore, gen16CodeId, ObjectKeys, parseQuery, updStore, callDispatchEvent} from "../../../stores/Utils";
import { get_resume__incms_expns, getall_categories, getFNMLabels } from "../services/customer_fetch_service";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";



const Svg = SvgIcon_Cmpt();



const ResumeCharts  = ({ data, confirm, label, item }) => {

	// const { modalID } = data;
	const [obs, set_obs] = useState(1);
	


	let location = useLocation();
	const navigate = useNavigate();

	//const navigate = useNavigate();
	const searchHash = location.search?.split("?")?.[1];
	const router = parseQuery(searchHash);

	let activeTab = router?.tab;


	

	useEffect(() => {
		
		getall_categories(loadResume);
		
	},[activeTab]);


	const loadResume =  (v) => {
		get_resume__incms_expns(loadChart);
	}

	
	const updObs =  (v) => {
		set_obs(gen16CodeId());
	}


	const loadChart =  (v) => {
		window.google.charts.load('current', {'packages':['corechart', 'line']});
		window.google.charts.setOnLoadCallback(drawChart);
		updObs();
	}
	

	const drawChart =  (v) => {
		drawDonutChart();
		// drawLineChart();
		
		var data = window.google.visualization.arrayToDataTable(getStore("graphCurveLineMonth"));

		var options = {
		  title: "",
		  curveType: 'function',
		  legend: { position: 'bottom' }
		};

		var chart = new window.google.visualization.LineChart(document.getElementById('curve_chart'));

		chart.draw(data, options);
	  }
	


	  function drawDonutChart() {
        var data = window.google.visualization.arrayToDataTable(getStore("graphDonutCMonth"));

        var options = {
          title: "",
          pieHole: 0.4,
        };

        var chart = new window.google.visualization.PieChart(document.getElementById('donutchart'));
        chart.draw(data, options);
	  }
	  
	let incomeT = getStore("resume_graph")?.[901]?.total ? (getStore("resume_graph")?.[901]?.total*1).toFixed(2) : "0.00";
	let expensesT = getStore("resume_graph")?.[902]?.total ? (getStore("resume_graph")?.[902]?.total*1).toFixed(2) : "0.00";




	const changeYear =  (y) => {
		updStore("date_current_year",y);
		let initDate = (new Date("01/01/"+y)).getTime(); 
		let lastDate = (new Date("01/01/"+(y+1))).getTime() - 10;
		updStore("date_range_comps", {initDate,lastDate} )
		updStore("date_range_submayor", {initDate,lastDate} )
		//updObs();
		//callDispatchEvent("dimention_hash");
		getall_categories(loadResume);
	}


	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeYYCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeYYCallModal", Date.now()+320);
			
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <YearChangeAlert
				confirm={changeYear}
			/>
			OpenModal(modaldata);
		}
	}


    return (
       
		<div className="mobile_version  " style={{margin: "65px 0" }} >
			<div className="listFlx  ">
				<p className="title_resume" onClick={OpenDeleteAlert}>
						{getFNMLabels(48) + ' '+ getStore("date_current_year")}
				</p>
			</div>

			<div className="_dsplFlx spaceAround  ">
				<div className="card_bx blue">
					<div className="title">
						{getFNMLabels(42)}
					</div>
					<div className="amount  ">
						${incomeT}
					</div>
				</div>
				<div className="card_bx red">
					<div className="title">
						{getFNMLabels(40)}
					</div>
					<div className="amount  ">
						${expensesT}
					</div>
				</div>
			</div>


				<div className="_dsplFlx itm_bx hdr " style={{margin:"40px auto 0"}}>
					<div>
						{getFNMLabels(65)}
					</div>
					<div className="flexSpace"/>
					<div  className="incomes">
						{getFNMLabels(42)}
					</div>
					<div className="expenses">
						{getFNMLabels(40)}
					</div>
				</div>

				{
					getStore("graphCurveLineMonth")?.map((dd,indd)=>{
						if(indd===0){
							return null;
						}

						let income = dd[1] ? (dd[1]*1).toFixed(2) : "0.00"
						let expenses = dd[2] ? (dd[2]*1).toFixed(2) : "0.00"

						return (
							<div className={`_dsplFlx itm_bx  ${indd%2===0?"shdow":""} `}  key={"mnt_key_"+dd[0]}>
								<div>
									{dd[0]}
								</div>
								<div className="flexSpace"/>
								<div  className="incomes">
									{income}
								</div>
								<div className="expenses">
									{expenses}
								</div>
							</div>
						)
					})
				}

			
			<div id="donutchart" style={{width: "99xvw", height: "50vw", margin:"20px auto"}}></div>
			
			
			

			<div className="listFlx  "  style={{margin:"40px auto 0"}}>
				<p className="title_resume" >
					{getFNMLabels(47)}
				</p>
			</div>
			
			<div className="_dsplFlx itm_bx hdr ">
				<div>
					{getFNMLabels(54)}
				</div>
				<div className="flexSpace"/>
				<div className="expenses">
					{getFNMLabels(40)}
				</div>
			</div>

			{
				getStore("resume_graph")?.categories  && ObjectKeys(getStore("resume_graph").categories)?.map((ctId,indd)=>{
					

					let expenses = getStore("resume_graph").categories?.[ctId]?.total  ? (getStore("resume_graph").categories?.[ctId]?.total*1).toFixed(2) : "0.00";

					let categoryLabel = getStore("categories_ids")?.[ctId]?.name;
	
	
					return (
						<div className={`_dsplFlx itm_bx  ${indd%2===0?"shdow":""} `} key={"categories_key_"+ctId}>
							<div>
								{categoryLabel}
							</div>
							<div className="flexSpace"/>
							<div className="expenses">
								{expenses}
							</div>
						</div>
					)
				})
			}

		<div id="curve_chart" style={{width: "99vw", height: "50vh", margin:"20px auto"}}></div>
			
		</div>
    )   
}

export default ResumeCharts;















const YearChangeAlert  = ({ data, confirm, labelColor }) => {

	const { modalID } = data;

	const handleClose =  (v) => {
		CloseModal({id:modalID})
    }
    
    const handleConfirm =  (y) => {
        confirm && confirm(y);
		handleClose();
	}



    return (
       
		<div style={{
			maxHeight: "80vh",
			minHeight:  "30vh",
			minWidth: "260px",
			width: "93vw",
			overflow: "auto",
			background: "var(--dark-800)",
			borderRadius: 13,
			border: "1px solid var(--partial-success)",
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title" style={labelColor?{color:labelColor}:null}>
					Change Years
				</p>
				<div className="flexSpace"/>
				
			</div>
			<div className="_dsplFlx  spaceAround flxWrp" style={{margin:"35px 0 10px"}}>
				
			<div className={`yyBx ${getStore("date_current_year")===2022?"activeY":""}`} onClick={()=>handleConfirm(2022)}>
					<h4>
						2022
					</h4>
				</div>
				<div className={`yyBx ${getStore("date_current_year")===2023?"activeY":""}`} onClick={()=>handleConfirm(2023)}>
					<h4>
						2023
					</h4>
				</div>
				<div className={`yyBx ${getStore("date_current_year")===2024?"activeY":""}`} onClick={()=>handleConfirm(2024)}>
					<h4>
						2024
					</h4>
				</div>

			</div>
		</div>
    )   
}


